#[test]
fn golden_foxglove_msgs_point2() {
    let golden = read_golden("foxglove_msgs", "Point2");
    let p: FoxglovePoint2 = decode_fixed(&golden).unwrap();
    assert_eq!(p.x, 10.5);
    assert_eq!(p.y, 20.5);
    let built = FoxglovePoint2 { x: 10.5, y: 20.5 };
    assert_eq!(encode_fixed(&built).unwrap(), golden);
    let mut m = p;
    m.x = 42.0;
    let re: FoxglovePoint2 = decode_fixed(&encode_fixed(&m).unwrap()).unwrap();
    assert_eq!(re.x, 42.0);
    assert_eq!(re.y, p.y);
}

