// ── edgefirst_msgs :: Tensor family ────────────────────────────────────────
//
// These goldens are produced by the pycdr2 dataclasses in
// benches/python/legacy/, an implementation of the same .msg contract that is
// entirely independent of the Rust encoder. A mismatch here means one of the
// two is wrong about layout, alignment, or field order — which is the only
// reason a golden is worth more than a round-trip test.

/// The NV12 fixture shared by the Tensor and wrapper goldens.
///
/// Referenced planes: one allocation, Y at offset 0 and UV at w*h. Unquantized,
/// so `quant_scales` is empty — `quant_axis == -2` requires that.
fn nv12_planes() -> Vec<TensorPlaneView<'static>> {
    const HANDLE_BYTES: &[u8] = &[0xDE, 0xAD, 0xBE, 0xEF];
    vec![
        TensorPlaneView {
            handle: 7,
            offset: 0,
            stride: 640,
            size: 640 * 480,
            used: 640 * 480,
            modifier: 0,
            handle_bytes: HANDLE_BYTES,
            data: &[],
        },
        TensorPlaneView {
            handle: 7,
            offset: 640 * 480,
            stride: 640,
            size: 640 * 480 / 2,
            used: 640 * 480 / 2,
            modifier: 0,
            handle_bytes: &[],
            data: &[],
        },
    ]
}

fn nv12_fields<'a>(planes: &'a [TensorPlaneView<'a>]) -> TensorFields<'a> {
    TensorFields {
        storage_kind: 2,
        pid: 4242,
        fence_fd: -1,
        dtype: 1,
        quant_axis: -2,
        shape: &[480, 640],
        strides: &[640, 1],
        quant_scales: &[],
        quant_zero_points: &[],
        format: "NV12".into(),
        color_space: "bt709".into(),
        color_transfer: "bt709".into(),
        color_encoding: "bt709".into(),
        color_range: "limited".into(),
        planes,
    }
}

#[test]
fn golden_edgefirst_msgs_tensor() {
    let golden = read_golden("edgefirst_msgs", "Tensor");

    // Phase 1 — decode and verify every field.
    let t = edgefirst_schemas::tensor::Tensor::from_cdr(golden.as_slice()).unwrap();
    assert_eq!(t.storage_kind(), 2);
    assert_eq!(t.pid(), 4242);
    assert_eq!(t.fence_fd(), -1);
    assert_eq!(t.dtype(), 1);
    assert_eq!(t.quant_axis(), -2);
    assert_eq!(t.shape().collect::<Vec<u64>>(), vec![480, 640]);
    assert_eq!(t.strides().collect::<Vec<i64>>(), vec![640, 1]);
    assert!(t.quant_scales().is_empty());
    assert!(t.quant_zero_points().is_empty());
    assert_eq!(t.format(), "NV12");
    assert_eq!(t.color_space(), "bt709");
    assert_eq!(t.color_transfer(), "bt709");
    assert_eq!(t.color_encoding(), "bt709");
    assert_eq!(t.color_range(), "limited");
    assert_eq!(t.num_planes(), 2);

    let planes: Vec<_> = t.planes().collect();
    assert_eq!(planes.len(), 2);
    assert_eq!(planes[0].handle, 7);
    assert_eq!(planes[0].offset, 0);
    assert_eq!(planes[0].stride, 640);
    assert_eq!(planes[0].size, 640 * 480);
    assert_eq!(planes[0].used, 640 * 480);
    assert_eq!(planes[0].modifier, 0);
    assert_eq!(planes[0].handle_bytes, &[0xDE, 0xAD, 0xBE, 0xEF]);
    assert!(planes[0].data.is_empty());
    assert!(!planes[0].is_inline());
    assert_eq!(planes[1].offset, 640 * 480);
    assert_eq!(planes[1].size, 640 * 480 / 2);
    assert!(planes[1].handle_bytes.is_empty());

    // Phase 2 — construct from scratch, assert byte-identical.
    let p = nv12_planes();
    let f = nv12_fields(&p);
    let mut b = edgefirst_schemas::tensor::Tensor::builder();
    b.storage_kind(f.storage_kind)
        .pid(f.pid)
        .fence_fd(f.fence_fd)
        .dtype(f.dtype)
        .quant_axis(f.quant_axis)
        .shape(f.shape)
        .strides(f.strides)
        .format("NV12")
        .color_space("bt709")
        .color_transfer("bt709")
        .color_encoding("bt709")
        .color_range("limited")
        .planes(f.planes);
    let built = b.build().unwrap();
    assert_eq!(built.as_cdr(), golden.as_slice());
}

#[test]
fn golden_edgefirst_msgs_tensor_inline() {
    let golden = read_golden("edgefirst_msgs", "Tensor_inline");

    let t = edgefirst_schemas::tensor::Tensor::from_cdr(golden.as_slice()).unwrap();
    assert_eq!(t.dtype(), 1);
    assert_eq!(t.format(), "mono8");
    assert_eq!(t.shape().collect::<Vec<u64>>(), vec![2, 4]);
    assert_eq!(t.num_planes(), 1);

    let p = t.plane_at(0).unwrap();
    assert!(p.is_inline());
    assert_eq!(p.handle, -1);
    assert_eq!(p.size, 8);
    assert_eq!(p.used, 8);
    assert_eq!(p.data, &[0, 1, 2, 3, 4, 5, 6, 7]);
    assert!(p.handle_bytes.is_empty());

    let data: Vec<u8> = (0..8).collect();
    let planes = [TensorPlaneView {
        handle: -1,
        offset: 0,
        stride: 4,
        size: 8,
        used: 8,
        modifier: 0,
        handle_bytes: &[],
        data: &data,
    }];
    let mut b = edgefirst_schemas::tensor::Tensor::builder();
    b.dtype(1)
        .shape(&[2, 4])
        .strides(&[4, 1])
        .format("mono8")
        .planes(&planes);
    assert_eq!(b.build().unwrap().as_cdr(), golden.as_slice());
}

#[test]
fn golden_edgefirst_msgs_tensor_quantized() {
    let golden = read_golden("edgefirst_msgs", "Tensor_quantized");

    let t = edgefirst_schemas::tensor::Tensor::from_cdr(golden.as_slice()).unwrap();
    assert_eq!(t.dtype(), 3);
    assert_eq!(t.quant_axis(), 0);
    assert_eq!(t.shape().collect::<Vec<u64>>(), vec![3, 8]);
    // Per-axis: exactly shape[0] scales.
    assert_eq!(t.quant_scales(), &[0.5, 0.25, 0.125]);
    assert_eq!(t.quant_zero_points(), &[128, 0, -128]);
    assert_eq!(t.num_planes(), 0);
    assert_eq!(t.strides().count(), 0);

    let mut b = edgefirst_schemas::tensor::Tensor::builder();
    b.dtype(3)
        .quant_axis(0)
        .shape(&[3, 8])
        .quant_scales(&[0.5, 0.25, 0.125])
        .quant_zero_points(&[128, 0, -128]);
    assert_eq!(b.build().unwrap().as_cdr(), golden.as_slice());
}

/// Both wrappers, decoded and rebuilt against the same golden pair.
///
/// Runs the whole check twice — once per wrapper — because "byte-identical"
/// is a claim about both, and a test that only exercised one would not notice
/// the other drifting.
macro_rules! golden_stamped_tensor_test {
    ($name:ident, $ty:ty, $golden:literal) => {
        #[test]
        fn $name() {
            let golden = read_golden("edgefirst_msgs", $golden);

            // Phase 1 — decode.
            let m = <$ty>::from_cdr(golden.clone()).unwrap();
            assert_eq!(m.stamp(), STAMP);
            assert_eq!(m.frame_id(), FRAME_ID);
            assert_eq!(m.seq(), 99);

            let t = m.tensor();
            assert_eq!(t.pid(), 4242);
            assert_eq!(t.format(), "NV12");
            assert_eq!(t.num_planes(), 2);
            assert_eq!(t.shape().collect::<Vec<u64>>(), vec![480, 640]);

            // Phase 2 — construct from scratch, assert byte-identical.
            let p = nv12_planes();
            let f = nv12_fields(&p);
            let built = <$ty>::builder()
                .stamp(STAMP)
                .frame_id(FRAME_ID)
                .seq(99)
                .tensor(&f)
                .build()
                .unwrap();
            assert_eq!(built.as_cdr(), golden.as_slice());

            // Phase 3 — modify in place and verify the roundtrip.
            let mut m = <$ty>::from_cdr(golden.clone()).unwrap();
            m.set_seq(1234).unwrap();
            assert_eq!(m.seq(), 1234);
            m.set_stamp(Time::new(1, 2)).unwrap();
            assert_eq!(m.stamp(), Time::new(1, 2));
            assert_ne!(m.as_cdr(), golden.as_slice());
            // A header-only edit must leave the payload untouched.
            assert_eq!(m.tensor().format(), "NV12");
            assert_eq!(m.tensor().num_planes(), 2);
        }
    };
}

golden_stamped_tensor_test!(
    golden_edgefirst_msgs_tensor_stamped,
    edgefirst_msgs::TensorStamped<Vec<u8>>,
    "TensorStamped"
);
golden_stamped_tensor_test!(
    golden_edgefirst_msgs_camera_frame,
    edgefirst_msgs::CameraFrame<Vec<u8>>,
    "CameraFrame"
);

/// The wrappers are byte-identical, and the goldens prove it independently.
///
/// Both files were produced by pycdr2 from separate dataclasses, so this
/// compares two independently-generated encodings rather than one buffer
/// against itself.
#[test]
fn golden_wrappers_are_byte_identical() {
    let stamped = read_golden("edgefirst_msgs", "TensorStamped");
    let frame = read_golden("edgefirst_msgs", "CameraFrame");
    assert_eq!(stamped, frame);

    // And each parses as the other.
    let as_frame = edgefirst_msgs::CameraFrame::from_cdr(stamped.as_slice()).unwrap();
    let as_stamped = edgefirst_msgs::TensorStamped::from_cdr(frame.as_slice()).unwrap();
    assert_eq!(as_frame.seq(), as_stamped.seq());
    assert_eq!(as_frame.frame_id(), as_stamped.frame_id());
    assert_eq!(as_frame.tensor().format(), as_stamped.tensor().format());
}

/// Position independence, checked against goldens rather than self-consistency.
///
/// `CameraFrame_long_frame_id` has a frame_id three times the length of
/// `CameraFrame`'s, so every header byte after `stamp` sits at a different
/// offset. The embedded tensor's bytes must nevertheless be identical, because
/// `seq` (uint64) forces the tensor to the same 8-aligned offset either way.
#[test]
fn golden_tensor_bytes_survive_frame_id_length_change() {
    let short = read_golden("edgefirst_msgs", "CameraFrame");
    let long = read_golden("edgefirst_msgs", "CameraFrame_long_frame_id");
    assert_ne!(
        short.len(),
        long.len(),
        "fixture must differ in header size"
    );

    let a = edgefirst_msgs::CameraFrame::from_cdr(short.as_slice()).unwrap();
    let b = edgefirst_msgs::CameraFrame::from_cdr(long.as_slice()).unwrap();
    assert_eq!(a.frame_id(), FRAME_ID);
    assert_eq!(b.frame_id(), "a_very_long_frame_identifier_x");

    // The payload bytes are identical despite the different headers.
    assert_eq!(a.tensor().tensor_bytes(), b.tensor().tensor_bytes());

    // The bases are NOT equal, and must not be: a frame_id 20 characters
    // longer pushes the tensor later in the buffer. What is invariant is the
    // base's alignment phase relative to the CDR data start at offset 4.
    // Landing on the same phase is precisely why the byte runs above match —
    // every interior field sits at the same offset relative to the base.
    // This is what `seq` being a uint64 rather than a uint32 buys: it absorbs
    // whatever padding frame_id leaves and re-establishes 8-alignment.
    assert_ne!(a.tensor().base(), b.tensor().base());
    assert_eq!((a.tensor().base() - 4) % 8, 0);
    assert_eq!((b.tensor().base() - 4) % 8, 0);

    // Re-heading either yields the same standalone Tensor message, which must
    // equal the standalone Tensor golden byte for byte.
    let standalone = read_golden("edgefirst_msgs", "Tensor");
    assert_eq!(a.tensor().to_standalone_cdr(), standalone);
    assert_eq!(b.tensor().to_standalone_cdr(), standalone);
}

fn build_tensor_from_fields(f: &TensorFields<'_>) -> edgefirst_schemas::tensor::Tensor<Vec<u8>> {
    let mut b = edgefirst_schemas::tensor::Tensor::builder();
    b.storage_kind(f.storage_kind)
        .pid(f.pid)
        .fence_fd(f.fence_fd)
        .dtype(f.dtype)
        .quant_axis(f.quant_axis)
        .shape(f.shape)
        .strides(f.strides)
        .quant_scales(f.quant_scales)
        .quant_zero_points(f.quant_zero_points)
        .format(f.format.as_ref())
        .color_space(f.color_space.as_ref())
        .color_transfer(f.color_transfer.as_ref())
        .color_encoding(f.color_encoding.as_ref())
        .color_range(f.color_range.as_ref())
        .planes(f.planes);
    b.build().unwrap()
}

fn i420_planes() -> Vec<TensorPlaneView<'static>> {
    const W: u64 = 1920;
    const H: u64 = 1080;
    let y_sz = W * H;
    let uv_sz = (W / 2) * (H / 2);
    vec![
        TensorPlaneView {
            handle: 42,
            offset: 0,
            stride: W,
            size: y_sz,
            used: y_sz,
            modifier: 0,
            handle_bytes: &[],
            data: &[],
        },
        TensorPlaneView {
            handle: 42,
            offset: y_sz,
            stride: W / 2,
            size: uv_sz,
            used: uv_sz,
            modifier: 0,
            handle_bytes: &[],
            data: &[],
        },
        TensorPlaneView {
            handle: 42,
            offset: y_sz + uv_sz,
            stride: W / 2,
            size: uv_sz,
            used: uv_sz,
            modifier: 0,
            handle_bytes: &[],
            data: &[],
        },
    ]
}

#[test]
fn golden_edgefirst_msgs_tensor_i420() {
    let golden = read_golden("edgefirst_msgs", "Tensor_i420");
    let t = edgefirst_schemas::tensor::Tensor::from_cdr(golden.as_slice()).unwrap();
    assert_eq!(t.format(), "I420");
    assert_eq!(t.num_planes(), 3);
    assert_eq!(
        t.planes().map(|p| p.handle).collect::<Vec<_>>(),
        vec![42, 42, 42]
    );

    let p = i420_planes();
    let f = TensorFields {
        storage_kind: 2,
        pid: 1234,
        fence_fd: -1,
        dtype: 1,
        quant_axis: -2,
        shape: &[1080, 1920],
        strides: &[1920, 1],
        quant_scales: &[],
        quant_zero_points: &[],
        format: "I420".into(),
        color_space: "bt709".into(),
        color_transfer: "bt709".into(),
        color_encoding: "bt709".into(),
        color_range: "limited".into(),
        planes: &p,
    };
    assert_eq!(build_tensor_from_fields(&f).as_cdr(), golden.as_slice());
}

#[test]
fn golden_edgefirst_msgs_camera_frame_split_fd() {
    let golden = read_golden("edgefirst_msgs", "CameraFrame_split_fd");
    let frame = edgefirst_msgs::CameraFrame::from_cdr(golden.as_slice()).unwrap();
    assert_eq!(frame.seq(), 5);
    assert_eq!(frame.tensor().fence_fd(), 77);
    assert_eq!(frame.tensor().num_planes(), 2);
    let handles: Vec<_> = frame.tensor().planes().map(|p| p.handle).collect();
    assert_eq!(handles, vec![70, 71]);

    let planes = vec![
        TensorPlaneView {
            handle: 70,
            offset: 0,
            stride: 1920,
            size: 2_073_600,
            used: 2_073_600,
            modifier: 0,
            handle_bytes: &[],
            data: &[],
        },
        TensorPlaneView {
            handle: 71,
            offset: 0,
            stride: 1920,
            size: 1_036_800,
            used: 1_036_800,
            modifier: 0,
            handle_bytes: &[],
            data: &[],
        },
    ];
    let f = TensorFields {
        storage_kind: 2,
        pid: 1234,
        fence_fd: 77,
        dtype: 1,
        quant_axis: -2,
        shape: &[1080, 1920],
        strides: &[1920, 1],
        quant_scales: &[],
        quant_zero_points: &[],
        format: "NV12".into(),
        color_space: "bt709".into(),
        color_transfer: "bt709".into(),
        color_encoding: "bt709".into(),
        color_range: "limited".into(),
        planes: &planes,
    };
    let tensor = build_tensor_from_fields(&f);
    let built = edgefirst_msgs::CameraFrame::builder()
        .stamp(STAMP)
        .frame_id(FRAME_ID)
        .seq(5)
        .tensor(&f)
        .build()
        .unwrap();
    assert_eq!(built.as_cdr(), golden.as_slice());
    assert_eq!(tensor.as_cdr(), frame.tensor().to_standalone_cdr());
}

